@push('scripts')<script>
(()=>{const viewer=document.getElementById('snapshotViewer'),title=document.getElementById('snapshotViewerTitle'),subtitle=document.getElementById('snapshotViewerSubtitle'),body=document.getElementById('snapshotViewerBody'),closeButton=document.getElementById('snapshotViewerClose');let previousFocus=null;function close(){viewer.style.display='none';viewer.setAttribute('aria-hidden','true');document.body.style.overflow='';if(previousFocus)previousFocus.focus();}document.querySelectorAll('.snapshot-view-trigger').forEach(button=>button.addEventListener('click',()=>{previousFocus=button;const kind=button.dataset.kind==='keterangan'?'Keterangan':'Spesifikasi';title.textContent=kind+' PC #'+button.dataset.pc;subtitle.textContent='Informasi baca-saja dari snapshot periode {{ $label }}.';const content=(button.dataset.content||'').trim();body.textContent=content||('Belum ada '+kind.toLowerCase()+' yang dicatat untuk PC ini.');body.classList.toggle('is-empty',!content);viewer.style.display='flex';viewer.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';closeButton.focus();}));closeButton.addEventListener('click',close);viewer.addEventListener('click',event=>{if(event.target===viewer)close()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&viewer.style.display==='flex')close()});})();
</script>@endpush
